import { Component, EventEmitter, Input, OnInit, Output, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { Subject, debounceTime } from 'rxjs';

@Component({
  selector: 'price-multiple-cards',
  templateUrl: 'price-multiple-cards.html',
  styleUrls: ['price-multiple-cards.scss'],
})
export class PriceMultipleCardsComponent implements OnInit, OnDestroy {
  @Input() rawPriceList;
  @Input() selectedPrice?;

  renderPriceList;

  private priceChangeSubject = new Subject<any>();
  priceChangeSubscription;

  @Output() handleChangePriceCard: EventEmitter<string> = new EventEmitter();
  constructor(
    public router: Router,
    public utils: Utils,
    public route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    this.priceChangeSubscription = this.priceChangeSubject.pipe(debounceTime(300)).subscribe((formatPrices) => {
      this.handleChangePriceCard.emit(formatPrices ?? null);
    });

    if (this.rawPriceList?.length) {
      this.renderPriceList = this.rawPriceList[0];
      this.selectedPrice = this.renderPriceList?.Options[0];
      this.formatSelectedPrice(this.selectedPrice);
    }
  }

  ngOnDestroy(): void {
    // Unsubscribe from the price change subscription
    if (this.priceChangeSubscription) {
      this.priceChangeSubscription.unsubscribe();
    }
  }

  formatSelectedPrice(price: any) {
    const formatPrices = this.rawPriceList?.map((item) => {
      return {
        ...item,
        Options: item?.Options?.filter((option) => option?.Id === price?.Id),
      };
    });
    this.priceChangeSubject.next(formatPrices);
  }

  changePriceCard(price: any) {
    this.selectedPrice = price;
    this.formatSelectedPrice(price);
  }
}
