import { Location } from '@angular/common';
import { ChangeDetectorRef, Component, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { NavController } from '@ionic/angular';
import { CategoryService } from '@rsApp/modules/browse/provider/category.service';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { Subject, takeUntil } from 'rxjs';
import { ProductSearchService } from '../../providers/product-search.service';

@Component({
  selector: 'app-products-search-list',
  templateUrl: './product-search-list.html',
  styleUrls: ['./product-search-list.scss'],
})
export class ProductSearchListPageComponent implements OnInit, OnDestroy {
  public slug: string;
  public loaded: boolean;
  public magProductSearchList = '';
  public keyword: string;
  public keywordClone: string;
  public queryParams: string;
  private _destroy$: Subject<boolean> = new Subject();

  constructor(
    public route: ActivatedRoute,
    public dxpComponentService: DxpComponentService,
    public categoryService: CategoryService,
    public router: Router,
    public cdr: ChangeDetectorRef,
    public productSearchService: ProductSearchService,
    public navCtrl: NavController,
    public location: Location
  ) {
    this.getRouteParams();
  }

  async ngOnInit() {
    this.slug = this.router.url;
    await this.dxpComponentService.onConnected();
    this.productSearchService
      .getCriterias()
      .pipe(takeUntil(this._destroy$))
      .subscribe((criterias) => {
        if (!criterias) {
          return;
        }
        this.updateQueryParams(criterias);
      });
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
    this.productSearchService.clearKeyWord();
  }

  getRouteParams() {
    const hasValue = (v: unknown) => v != null && v !== '';

    const queryParams = Object.fromEntries(
      Object.entries(this.route.snapshot.queryParams).filter(([, v]) => hasValue(v))
    );

    if (Object.keys(queryParams).length) {
      this.productSearchService.setCriterias(queryParams);
    }
  }

  changeKeyword(keyword: any) {
    const kw = keyword;
    if (this.keywordClone != kw) {
      this.loaded = false;
      this.cdr.detectChanges();
      this.keywordClone = kw;
      this.keyword = kw.replace(/\s+/g, '-'); // Remove spacing kw to get widget-layout
      this.loaded = true;
    }
  }

  updateQueryParams(params) {
    const cats = this.parseParam(params?.cats);
    const brands = this.parseParam(params?.brands);
    const queryParams = {
      Categories: cats.length ? cats : null,
      Brands: brands.length ? brands : null,
    };
    this.queryParams = JSON.stringify(queryParams);
    this.slug = this.router.url;

    this.changeKeyword(params?.keyword || '');
  }

  parseParam(param: any) {
    return param ? (Array.isArray(param) ? param : typeof param === 'string' ? param.split(';') : [param]) : [];
  }
}
