import { Component, EventEmitter, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { IMagParityProduct } from '../../../model/interface';
import { pricingUnit } from '../../../model/util';

@Component({
  selector: 'parity-product-flavor',
  templateUrl: 'parity-product-flavor.html',
  styleUrls: ['parity-product-flavor.scss'],
})
export class ParityProductFlavorComponent implements OnInit, OnDestroy {
  @Input() selecteđId: number;
  @Input() listProduct: IMagParityProduct[];
  @Input() storeCode: number;
  @Input() selectedProductUpc: string;
  @Input() parityName: string;

  @Output() changeFlavor: EventEmitter<any> = new EventEmitter();

  magImg: string = `<mag-img src></mag-img>`;

  selectedProduct: IMagParityProduct;
  listFormattedProduct: IMagParityProduct[];
  slidesPreView = 0;

  // @Output() onChangePriceCard: EventEmitter<string> = new EventEmitter(); ---- TODO
  constructor(
    public router: Router,
    public route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    window.addEventListener('resize', () => this._initSwiper());
    this._initSwiper();
    this.mappingProduct();
    this.selectedProduct =
      this.listFormattedProduct.find((product) => product?.Upc === this.selectedProductUpc) ||
      this.listFormattedProduct[0];
  }

  ngOnDestroy(): void {
    window.removeEventListener('resize', () => {
      console.log();
    });
  }

  private _initSwiper() {
    this.slidesPreView = window.innerWidth < 767 ? 1.75 : 3.25;
  }

  mappingProduct() {
    this.listFormattedProduct = this.listProduct.map((product) => {
      // Filter store and map the prices
      const filteredStore = product?.Stores?.[0];

      const storePrices = filteredStore?.Prices?.sort((p1, p2) => p1?.Price - p2?.Price);
      const [salePrice, regularPrice] =
        storePrices?.length > 1
          ? [storePrices[0], storePrices[1]]
          : storePrices?.length === 1
            ? [undefined, storePrices[0]]
            : [undefined, undefined];
      return {
        ...product,
        DisplaySalePrice: salePrice?.DisplayPrice,
        DisplayPrice: regularPrice?.DisplayPrice,
        DisplayPricingUnit: pricingUnit[regularPrice?.PricingUnit],
        PricingUnit: salePrice?.PricingUnit || regularPrice?.PricingUnit,
        PricePerUnitItem: salePrice?.PricePerUnitItem || regularPrice?.PricePerUnitItem,
      };
    });
  }

  onSelectProduct(product: IMagParityProduct) {
    this.selectedProduct = product;
    this.changeFlavor.emit(product);
    // console.log('Selected Flavor: ', this.selectedProduct);
  }
}
