import { Component, Input, OnDestroy, OnInit } from '@angular/core';

@Component({
  selector: 'product-content-collapse',
  templateUrl: 'product-content-collapse.html',
  styleUrls: ['product-content-collapse.scss'],
})
export class ProductContentCollapseComponent implements OnInit, OnDestroy {
  @Input() content: string;
  @Input() title?: string = '';
  @Input() type?: string = '';

  contentClass;
  isReadMore: boolean = true;
  hideReadMore: boolean = false;
  contentClasses = {};

  ngOnInit() {
    this.hideReadMore = this.content?.length < 250; // TODO
    this.contentClass = this.computeContentClasses();
  }

  ngOnDestroy() {
    this.isReadMore = true;
    this.hideReadMore = false;
  }

  computeContentClasses() {
    const isValidType = !!this.type;
    const style = {
      'product-content-collapse__content': this.isReadMore && !this.hideReadMore,
    };
    if (!isValidType) {
      return {
        'product-content-collapse__content': this.isReadMore && !this.hideReadMore,
      };
    }
    style[`product-content-collapse__content--${this.type}`] = true;
    return style;
  }

  changeDesView() {
    this.isReadMore = !this.isReadMore;
    this.contentClass = this.computeContentClasses();
  }
}
