import { Component, Input, OnInit, OnDestroy } from '@angular/core';
import { ModalController } from '@ionic/angular';
import { cloneDeep } from 'lodash';
import {
  getOptionSetsPhotos,
  getSubmitOptionSets,
  getSubmitOptionSetsGroup,
  getRenderOptionSets,
  getTotalOptionsPrices,
  formatData,
} from '../../model/util';
import { BehaviorSubject, debounceTime, Subject, takeUntil } from 'rxjs';
import { ProductService } from '../../providers/product.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { IMagOptionPhoto, IMagOptionSet, IMagOptionSetGroup, IMagProductRes } from '../../model/interface';

@Component({
  selector: 'product-options-modal',
  templateUrl: 'product-options-modal.html',
  styleUrls: ['product-options-modal.scss'],
})
export class ProductOptionsModalComponent implements OnInit, OnDestroy {
  @Input() productOptionSet: IMagOptionSetGroup[];
  @Input() selectedOptionSets;
  @Input() regularPrice?;
  @Input() quantity?: number;
  @Input() rawProduct: IMagProductRes;
  @Input() productName: string;
  @Input() isEdit = false;
  @Input() defaultImage: string;
  @Input() inCartProducts = [];
  @Input() cartItemId: string;

  totalVal: number;

  btnMode = 'MODAL';
  submitOptions: any = [];
  allOptionSetsWithSelectedValue: IMagOptionSet[];
  renderOptionSets: IMagOptionSet[] = [];
  private _destroy$: Subject<boolean> = new Subject();

  seletedOptions$ = new BehaviorSubject<IMagOptionSet[]>([]);
  optionPhotos$ = new BehaviorSubject<IMagOptionPhoto[]>([]);

  constructor(
    private modalCtrl: ModalController,
    public productService: ProductService,
    public utils: Utils
  ) {}

  // Lifecycle Hooks
  ngOnInit(): void {
    try {
      this.subscribeToSelectedOptions();

      if (this.defaultImage) {
        this.defaultImage = JSON.parse(this.defaultImage)[0];
      }
      this.regularPrice = parseFloat(this.regularPrice?.replace(/\$/g, '')) || 0;
      this.allOptionSetsWithSelectedValue = formatData(this.productOptionSet, this.isEdit, this.selectedOptionSets);
      this.prepareRenderOptionSets(this.productOptionSet, this.allOptionSetsWithSelectedValue);
      window.addEventListener('actionSuccess', (event: CustomEvent) => this.handleActionSuccess(event));
    } catch (err) {
      console.error(err);
    }
  }

  handleActionSuccess(event: CustomEvent) {
    if (event?.detail) {
      this.closeModal();
    }
  }

  ngOnDestroy(): void {
    this._destroy$.next(true);
    this._destroy$.complete();
    window.removeEventListener('actionSuccess', (event: CustomEvent) => this.handleActionSuccess(event));
  }

  private subscribeToSelectedOptions(): void {
    this.seletedOptions$.pipe(takeUntil(this._destroy$), debounceTime(300)).subscribe((optionSets: IMagOptionSet[]) => {
      if (optionSets) {
        this.setPhotos(optionSets);
        this.renderOptionSets = optionSets;
        this.totalVal = getTotalOptionsPrices(optionSets, this.regularPrice) * (this.quantity || 1);
        this.transformDataForSubmit(optionSets);
      }
    });
  }

  prepareRenderOptionSets(optionSetsGroup: IMagOptionSetGroup[], allOptionSetsWithSelectedValue: IMagOptionSet[]) {
    const rs = getRenderOptionSets(cloneDeep(optionSetsGroup), cloneDeep(allOptionSetsWithSelectedValue));
    this.seletedOptions$.next(rs);
  }

  setPhotos(optionSets: IMagOptionSet[]) {
    // Scan all option sets from (Final render data) to get SelectedOptionImage, SelectedOptionValue, ParentDisplayOrder.
    // Z-index is determine by ParentDisplayOrder * 100 + idx.
    if (!optionSets) return;
    const photos = getOptionSetsPhotos(optionSets);
    if (photos?.length) {
      this.defaultImage = null;
    }
    this.optionPhotos$.next(photos);
  }

  transformDataForSubmit(optionSets: IMagOptionSet[]) {
    const submitOptionSets = getSubmitOptionSets(cloneDeep(optionSets));
    const submitOptionSetsGroup = getSubmitOptionSetsGroup(submitOptionSets, cloneDeep(this.productOptionSet));
    if (submitOptionSetsGroup?.length) {
      this.submitOptions = submitOptionSetsGroup;
    }
  }

  onChangeOption(optionSet: IMagOptionSet) {
    const foundOptionSet = this.allOptionSetsWithSelectedValue.find((item) => item.Id === optionSet.Id);
    if (foundOptionSet) {
      Object.assign(foundOptionSet, optionSet);
    }

    this.prepareRenderOptionSets(this.productOptionSet, this.allOptionSetsWithSelectedValue);
  }

  // Modal functions
  closeModal() {
    return this.modalCtrl.dismiss();
  }
}
