import { Component, Input, OnChanges, ChangeDetectorRef, OnInit } from '@angular/core';
import { ENV } from '@app/env';

@Component({
  selector: 'custom-img',
  templateUrl: 'custom-img.html',
  styleUrls: ['custom-img.scss'],
})
export class CustomImgComponent implements OnChanges, OnInit {
  @Input()
  public src: string;
  @Input()
  public alt = '';
  @Input()
  public styles?: any = {};
  @Input() isFit?: boolean = false;
  @Input() objectFit?: string;
  @Input() displayDefaultImage?: boolean = true;
  @Input() imgSize?: string;

  public default: string;
  public cached: boolean;
  public loaded: boolean;
  public error: boolean;
  public isFullWidth: boolean;
  public isFullHeight: boolean;
  public isCover: boolean;
  public isContain: boolean;
  private lastSrc: string;
  public originSrc: string;
  public originImgSize: string;

  constructor(private cd: ChangeDetectorRef) {
    try {
      this.default = ENV.DefaultImg;
      this.cached = false;
      this.loaded = false;
      this.error = false;
      this.isFullWidth = false;
      this.isFullHeight = false;
    } catch (err) {
      console.error(err);
    }
  }

  ngOnInit() {
    this.cd.detectChanges();
  }

  public ngOnChanges() {
    if (this.imgSize && this.originSrc !== this.src) {
      this.originSrc = this.src;
      this.originImgSize = this.imgSize;
      this.src = this.src + `?imgsize=${this.imgSize}`;
    }
    this.isContain = this.objectFit === 'contain';
    this.isCover = this.objectFit === 'cover';
    if (this.src !== this.lastSrc) {
      this.lastSrc = this.src;
      this.loaded = false;
      this.error = false;
      this.cached = this.isCached(this.src);
    }

    if (!this.src) {
      this.error = true;
    }
  }

  public onLoad() {
    this.loaded = true;
  }

  public onError() {
    if (this.imgSize) {
      setTimeout(() => {
        this.src = this.originSrc;
        this.imgSize = null;
        //Get image origin
        this.ngOnChanges();
        // this.requestResizeImage(src);
      });
    } else {
      this.error = true;
    }
  }

  private isCached(url: string): boolean {
    if (!url) {
      return false;
    }

    const image = new Image();
    image.src = url;

    image.onload = () => {
      // Re-calculate image position
      if (image.width > image.height) {
        this.isFullHeight = true;
      } else if (image.height > image.width) {
        this.isFullWidth = true;
      } else {
        this.isFullHeight = this.isFullWidth = true;
        this.isCover = !this.isContain ? true : false;
      }
    };

    return image.complete;
  }
  async requestResizeImage(src: string) {
    try {
      src = src.replace('get-resized-image', 'resize-image');
      await fetch(src);
    } catch (error) {
      console.error(error);
    }
  }
}
