import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { ProductModule } from './product.module';
import { ProductDetailPageComponent } from './pages/product-detail/product-detail';
import { ProductSearchListPageComponent } from './pages/product-search-list/product-search-list';
import { ProductEndcapPageComponent } from './pages/product-endcap/product-endcap';

const routes: Routes = [
  {
    path: '',
    component: ProductDetailPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'product-detail/:slug',
    component: ProductDetailPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'product-search-list',
    component: ProductSearchListPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'endcap/:endcapCode',
    component: ProductEndcapPageComponent,
    data: {
      hideTab: true,
    },
  },
];

export default routes;

@NgModule({
  imports: [RouterModule.forChild(routes), ProductModule],
  declarations: [],
})
export class ProductRoutingModule {}
