import { Component, Input, OnInit, SimpleChanges, OnDestroy, OnChanges } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { ModalController } from '@ionic/angular';
import { ProductOptionsModalComponent } from '../product-options-modal/product-options-modal';
import { GiftCardOptionsModalComponent } from '../gift-card-options-modal/gift-card-options-modal';
import { BehaviorSubject, Subscription } from 'rxjs';
import { getOptionSetsByType } from '../../model/util';
// import { escape } from 'lodash';

@Component({
  selector: 'product-added',
  templateUrl: 'product-added.html',
  styleUrls: ['product-added.scss'],
})
export class ProductAddedComponent implements OnInit, OnDestroy, OnChanges {
  @Input() configData: any;
  @Input()
  set inCartProducts(value: any[]) {
    if (value) {
      this.inCartProductSubject.next(this.transformData(value));
    }
  }

  private inCartProductSubject = new BehaviorSubject<any[]>([]);
  inCartProducts$ = this.inCartProductSubject.asObservable();
  private subscriptions: Subscription = new Subscription();

  productType: string;
  btnMode = 'CART';

  constructor(
    public router: Router,
    public utils: Utils,
    public route: ActivatedRoute,
    public modalCtrl: ModalController
  ) {}

  // Lifecycle hooks
  ngOnInit(): void {
    this.productType = this.configData?.productType;
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes.configData) {
      this.productType = this.configData?.productType;
    }

    if (changes?.inCartProducts && changes?.inCartProducts?.currentValue) {
      this.inCartProductSubject.next(this.transformData(changes.inCartProducts.currentValue));
    }
  }

  // Data Retrieval and Handling
  transformData(products) {
    if (!products) return;
    products.forEach((item) => {
      item['seletedOptions'] = getOptionSetsByType(item?.rawSelectedOptionsets, item?.productType);
    });
    return products;
  }

  renderData(option) {
    if (!option?.OptionSetDisplayName) {
      return option?.DisplayName?.En + ':' + option?.Value;
    }
    switch (option?.OptionSetDisplayName) {
      case 'Style':
        return option?.OptionSetDisplayName + ':' + option?.DisplayName?.En;

      case 'Amount':
        return option?.OptionSetDisplayName + ':' + option?.PriceModifier;
    }
  }

  // Modal functions
  async openGiftCardOptionsModal(product?) {
    const { productOptionSet, regularPrice, productName, shoppingMode, rawProduct, productId, storeCode } =
      this.configData;

    const modal = await this.modalCtrl.create({
      cssClass: 'gift-card-options-modal',
      component: GiftCardOptionsModalComponent,
      componentProps: {
        giftCardOptions: productOptionSet,
        productName: productName,
        totalPrice: regularPrice,
        isEdit: true,
        rawProduct: rawProduct,
        shoppingMode: shoppingMode,
        productId: productId,
        storeCode: storeCode,
        selectedOptionSets: product?.rawSelectedOptionsets,
        quantity: product?.quantity,
        cartItemId: product?.cartItemId,
      },
      breakpoints: [0, 0.5, 1],
      initialBreakpoint: 1,
      handle: false,
    });

    modal.onDidDismiss().then((detail: any) => {
      console.log('Gift card options selected  ====>', detail);
    });

    return await modal.present();
  }

  async openProductOptionsModal(product?) {
    const {
      defaultImage,
      productOptionSet,
      regularPrice,
      productName,
      shoppingMode,
      rawProduct,
      productId,
      storeCode,
    } = this.configData;
    const modal = await this.modalCtrl.create({
      cssClass: 'product-options-modal',
      component: ProductOptionsModalComponent,
      componentProps: {
        productOptionSet: productOptionSet,
        regularPrice: regularPrice,
        productName: productName,
        shoppingMode: shoppingMode,
        rawProduct: rawProduct,
        productId: productId,
        storeCode: storeCode,
        isEdit: true,
        defaultImage: defaultImage,
        selectedOptionSets: product?.rawSelectedOptionsets,
        quantity: product?.quantity,
        cartItemId: product?.cartItemId,
      },
      breakpoints: [0, 0.5, 1],
      initialBreakpoint: 1,
      handle: false,
    });

    modal.onDidDismiss().then((detail: any) => {
      console.log('Options selecteds  ====>', detail);
    });

    return await modal.present();
  }
}
