import { Component, HostListener, NgZone, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { toBoolean, Utils } from '@rsApp/modules/utils/providers/utils';
import { ProductService } from '../../providers/product.service';
import { ModalController, NavController } from '@ionic/angular';
import { GiftCardOptionsModalComponent, ProductOptionsModalComponent } from '../../product.module';
import { Subject, combineLatest, firstValueFrom, from, take, takeUntil, tap } from 'rxjs';
import { ICartProductItem, IMagPrice, IMagProduct, IMagProductRes } from '../../model/interface';
import { CurrentStore, StoreService } from '@rsApp/modules/store/store.module';
import { renderLeadTime, pricingUnit } from '../../model/util';
import { ProductDealService } from '../../providers/product-deal.service';
import { ActionType } from '@rsApp/modules/utils/enum/enum';
import { upperFirst } from 'lodash';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { LOCAL_LOCALE_KEY } from '@rsApp/modules/utils/constants/constants';
import { Storage } from '@ionic/storage';
import { GoogleAnalyticTracker } from '@rsApp/modules/utils/providers/google-tracker.service';
import { RSTracker } from '@rsApp/modules/utils/providers/rs-tracker.service';
import { DXPTracker } from '@rsApp/modules/utils/providers/dxp-tracker.service';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { IMagProductDeal } from '@rsApp/modules/ecom-v2/offer/model/interface';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { ShoppingListService } from '@rsApp/modules/ecom-v2/shopping-list/providers/shopping-list.service';
import { RouteTrackerService } from '@rsApp/modules/utils/providers/route-tracker.service';
import { enumDiscountType } from '../../model/enum';
import { EditOrderService } from '@rsApp/modules/ecom-v2/edit-order.service';

@Component({
  selector: 'product-detail',
  templateUrl: 'product-detail.html',
  styleUrls: ['product-detail.scss'],
})
export class ProductDetailPageComponent implements OnInit {
  productRes: IMagProductRes;
  product: IMagProduct;
  similarProducts: string;
  slug: string;
  isProductWithOption = false;
  isGiftCard = false;
  store: any;
  productDes: string;
  isInstoreOnly = false;
  productStore: any;
  productLeadTime: string;
  buttonName = 'Add to Cart';
  inCartProducts: any;
  shoppingMode: string;
  addedProductConfig: any = {};
  isEdit = false;
  selectedOptionSets: any = [];
  itemId = '';
  productOffers: IMagProductDeal[];
  JSON: any = JSON;
  quantity;
  isPriceMultiplier = false;
  magQuanityBtn: string;
  magGallery: string;
  productDeclaimer: string;
  isDisplayUnitPrice = true;

  selectedOptions: any;
  btnMode = 'DETAIL';
  isButtonQuantityReady: boolean;

  categoryDepartment: string;
  magImg: string = '<mag-img src></mag-img>';
  loaded: boolean;
  isShoppingList: boolean = false;
  isAddedShoppingList: boolean = false;
  currentUser: any;
  isEditMode: boolean = false;
  isLoading = false;
  private _destroy$ = new Subject();
  private _initCompleted$ = new Subject<void>();
  private messageHandler = (event) => {
    this.handleMessage(event);
  };

  systemService: any;
  public isUnavailable: boolean = false;

  constructor(
    public router: Router,
    public utils: Utils,
    public route: ActivatedRoute,
    public productService: ProductService,
    public productDealService: ProductDealService,
    private modalCtrl: ModalController,
    public cStore: CurrentStore,
    public navCtrl: NavController,
    public appSettings: AppSettings,
    private storage: Storage,
    private googleTracking: GoogleAnalyticTracker,
    private rsTracking: RSTracker,
    private dxpTracking: DXPTracker,
    private auth: AuthService,
    public cre: Credential,
    private routeTracker: RouteTrackerService,
    private shoppingListSvc: ShoppingListService,
    private ngZone: NgZone,
    public storeService: StoreService,
    private shoppingCartService: EditOrderService
  ) {
    this.route.params.subscribe((param) => {
      const { slug } = param;
      this.slug = slug;
    });
  }

  @HostListener('window:message', ['$event'])
  onMessage(event) {
    this.messageHandler(event);
  }

  ngOnInit() {
    this._initCompleted$.pipe(take(1), takeUntil(this._destroy$)).subscribe(() => {
      this.getProductDeclaimer();
      this.loadSimilarProducts();
      this.shoppingListSvc.handleGetShoppingListByUserId();
      this.shoppingListSvc
        .getCurrentShoppingList()
        .pipe(takeUntil(this._destroy$))
        .subscribe({
          next: (currentShoppingList) => {
            if (currentShoppingList && this.product) {
              const productInList = currentShoppingList.Items?.find(
                (item) => item.ProductId === this.product.ProductId
              );
              this.ngZone.run(() => {
                this.isAddedShoppingList = !!productInList;
              });
            }
          },
          error: (err) => console.warn(err),
        });
    });
  }

  initData() {
    combineLatest([this.shoppingCartService.cartObs(), from(this.init())])
      .pipe(
        takeUntil(this._destroy$),
        tap(([editOrder, product]) => {
          if (editOrder && product) {
            this.isValidLeadTime();
          }
        })
      )
      .subscribe(() => {
        this._initCompleted$.next();
        this._initCompleted$.complete();
      });
  }

  async ionViewWillEnter() {
    try {
      this.currentUser = this.cre.currentUser;
      this.initData();
    } catch (error) {
      console.error(error);
    }
  }

  ionViewDidLeave() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  async init() {
    this.store = await this.cStore.getStore();

    if (!this.store) {
      console.warn('Store not found');
      return;
    }

    await this.refreshProductOffers();
    await this.getStoreSystemServices();
    this.productStore =
      this.productRes &&
      this.productRes.Stores?.find((item) => String(item?.StoreCode) === String(this.store?.StoreCode));
    this.mappingProduct(this.productRes);
    this.isInstoreOnly =
      !this.product?.IsOutOfStock && !this.product?.Pickup && !this.product?.Delivery && !this.product?.Mail;
    this.productLeadTime = renderLeadTime(this.product?.LeadTime);
    this.categoryDepartment = this.product?.Categories?.find((category) => category?.Level === 1)?.CategoryName;

    this.detectProductType();
    this.updateMagQuantityButton(null);
    this.updateMagGallery();
    this.handleEventTracking();
    this.isProductUnavailable();
    this.isShoppingList = !(await this.routeTracker.checkIsAvaiableCheckoutProductSvc(this.productRes));

    if (this.isProductWithOption) {
      this.subscribeRouteParams();
    }

    this.loaded = true;
    this.utils.hideLoading();
    return this.product;
  }

  async isValidLeadTime() {
    const { isEditMode, getExpireTimeEditOrder } = this.shoppingCartService;
    const { LeadTime } = this.product;
    if (!isEditMode() || !LeadTime) return (this.isEditMode = false);
    const expTime = await getExpireTimeEditOrder();
    if (LeadTime >= expTime) return (this.isEditMode = true);
  }

  handleEventTracking() {
    const priceProduct = this.googleTracking.getPriceFromProduct(this.productRes);
    const data = this.googleTracking.convertProductData(this.productRes);

    this.googleTracking.gtagTrackViewItem(data);
    this.rsTracking.trackProductView(this.product);
    this.dxpTracking.handlePushDxpTracking('trackViewProduct', {
      Price: priceProduct?.salePrice ? priceProduct?.salePrice : priceProduct?.price,
      Name: this.productRes?.Name?.En,
      UPC: this.productRes?.Upc,
      BrandName: this.productRes?.BrandName?.BrandName,
      Category: this.productRes?.Categories?.map((category) => category.CategoryName).join(', '),
    });
  }

  async handleMessage(event) {
    if (event?.data?.action === ActionType.MagReloadItemInCart && this.isProductWithOption) {
      await this.refreshCart();
    }
  }

  async applyLocale(message: string): Promise<string | undefined> {
    if (!message) return;
    const parsedMessage = JSON.parse(message);
    const currentLocale = await this.storage.get(LOCAL_LOCALE_KEY);
    const transfromLocale = currentLocale && upperFirst(currentLocale);
    return parsedMessage?.[transfromLocale];
  }

  async getProductDeclaimer() {
    try {
      const res = await firstValueFrom(this.appSettings.getSettingValue('Product_Disclaimer'));
      const localizeMessage = res && (await this.applyLocale(res));
      if (!localizeMessage) return;
      this.productDeclaimer = localizeMessage;
    } catch (error) {
      console.error('Error fetching product disclaimer:', error);
    }
  }

  updateMagQuantityButton(optionSet): void {
    this.selectedOptions = optionSet ? [...optionSet] : null;
    this.isButtonQuantityReady = true;
  }

  updateMagGallery(): void {
    const isProductOnSale =
      this.product?.IsOnSale || this.productStore?.Prices?.some((x) => x.PriceType === 'SalePrice') || false;
    if (!this.product?.Images) {
      this.magImg = `<mag-img display-sale-tag='${isProductOnSale}' src></mag-img>`;
      return;
    }

    this.magGallery = `<mag-gallery display-sale-tag='${isProductOnSale}' image-string='${this.product?.Images}'></mag-gallery>`;
  }

  handleChangePriceCard(optionSet) {
    if (!optionSet) {
      console.error('optionSet not found');
      return;
    }
    this.updateMagQuantityButton(optionSet);
  }

  isCustomer() {
    return this.auth?.cre?.currentUser;
  }

  async loadCartsPreview() {
    try {
      const guestCartIds = this.productService.getGuestCartIds();
      const isCustomer = this.isCustomer();
      if (!guestCartIds && !isCustomer) {
        console.warn('Failed to loadCartsPreview', guestCartIds, isCustomer);
        return;
      }
      const cartPreview = await firstValueFrom(this.productService.getMultiCartPreview(guestCartIds));
      return cartPreview?.Items?.filter((item: ICartProductItem) => item?.Upc === this.slug);
    } catch (error) {
      console.error('Error: getMultiCartPreview', error);
    }
  }

  async getCartData() {
    try {
      const cartData = await this.loadCartsPreview();
      if (!cartData) {
        console.warn('Failed to loadCartsPreview', cartData);
        return;
      }
      const formatCartData = cartData?.map((item: ICartProductItem) => {
        return {
          cartItemId: item?.Id,
          rawSelectedOptionsets: item?.OptionSets,
          productType: item?.ProductType,
          totalPrice: item?.TotalPrice,
          quantity: item?.Quantity,
        };
      });

      if (!formatCartData) return;

      return formatCartData;
    } catch (err) {
      console.error(err);
    }
  }

  async refreshCart() {
    const data = await this.getCartData();
    this.ngZone.run(() => {
      if (data) {
        this.inCartProducts = data;
      }
      this.addedProductConfig = this.configOptionsModal();
      this.utils.hideLoading();
    });
  }

  detectEditModeFromCart() {
    if (!this.isEdit || !this.itemId) return;
    const productFromEdit = this.inCartProducts?.find((item) => item?.cartItemId === this.itemId);
    this.quantity = productFromEdit?.quantity;
    this.selectedOptionSets = productFromEdit?.rawSelectedOptionsets;
    if (this.selectedOptionSets?.length) {
      this.openSelectOptionModal();
    }
  }

  private subscribeRouteParams() {
    this.route.params.pipe(takeUntil(this._destroy$)).subscribe(async (param) => {
      const { itemId } = param;
      await this.refreshCart();
      if (itemId) {
        this.itemId = itemId;
        this.isEdit = true;
        this.detectEditModeFromCart();
        this.isEdit = false;
      }
    });
  }

  configOptionsModal() {
    const config = {
      productOptionSet: this.product?.OptionSets,
      regularPrice: this.product?.DisplayPrice,
      productName: this.product?.DisplayName?.En || this.product?.Name?.En,
      shoppingMode: this.shoppingMode,
      rawProduct: this.productRes,
      productId: this.product?.ProductId,
      storeCode: this.store?.StoreCode,
      productType: this.product?.ProductType,
      defaultImage: this.product?.Images,
    };
    return config;
  }

  async loadSimilarProducts() {
    try {
      const products =
        this.productRes &&
        (await firstValueFrom(this.productService.getSimilarProducts(this.productRes?.Upc, this.store?.StoreCode)));
      if (!products || !products.length) return;

      this.similarProducts = JSON.stringify(products);
      this.getOffersForSimilarProduct(products);
    } catch (error) {
      console.error('Error: loadSimilarProducts', error);
    }
  }

  mappingProduct(productRes: IMagProductRes) {
    const {
      Name,
      DisplayName,
      Brands,
      Unit,
      MediaAssets,
      FullDescription,
      ShortDescription,
      Instructions,
      MinPurchaseQuantity,
      MaxPurchaseQuantity,
      Upc,
      AgeRestricted,
      AgeRestrictedValue,
      Pickup,
      Delivery,
      IsOutOfStockAllStore,
      LeadTime,
      Parity,
      ProductType,
      OptionSets,
      Nutritional,
      ProductId,
      IsDynamicSize,
      Categories,
      HazardPrecautionaryStatement,
      LoyaltyProgramIndicator,
      PromoCollections,
      Stores,
      Mail,
      Nutrients,
      NutrientOverview,
      Ingredients,
    } = productRes;

    const priceItem = this.productStore?.Prices?.find((priceItem: IMagPrice) => priceItem?.PriceType === 'Price');

    const salePriceItem = this.productStore?.Prices?.find(
      (priceItem: IMagPrice) => priceItem?.PriceType === 'SalePrice'
    );

    const images = MediaAssets?.Images?.map((img) => {
      return img.ImgUrlOriginal;
    });

    const productServiceId = Stores?.[0]?.Services?.[0]?.ServiceId;
    const AisleDisplayName = this.productStore?.Locations?.[0]?.AisleDisplayName;
    this.product = {
      Name,
      DisplayName,
      Images: images && images?.length > 0 ? JSON.stringify(images) : null,
      DisplaySalePrice: salePriceItem && salePriceItem?.DisplayPrice,
      PricingUnit: salePriceItem?.PricingUnit || priceItem?.PricingUnit,
      PricePerUnitItem: salePriceItem?.PricePerUnitItem || priceItem?.PricePerUnitItem,
      Unit,
      HazardPrecautionaryStatement,
      DisplayPrice: priceItem?.DisplayPrice,
      DisplayPricingUnit: pricingUnit[priceItem?.PricingUnit],
      MinPurchaseQuantity,
      MaxPurchaseQuantity,
      Brand: Brands?.length > 0 ? Brands[0]?.BrandName : '',
      Department: AisleDisplayName ? `Aisle ${AisleDisplayName}` : null,
      Upc,
      FullDescription,
      ShortDescription,
      Instructions,
      AgeRestricted,
      AgeRestrictedValue,
      Pickup,
      Delivery,
      IsOutOfStock: this.productStore?.IsOutOfStock,
      IsOutOfStockAllStore,
      LeadTime,
      Parity,
      ProductType,
      OptionSets,
      Nutritional,
      Nutrients,
      NutrientOverview,
      ProductId: ProductId,
      IsDynamicSize: IsDynamicSize,
      Categories,
      LoyaltyProgramIndicator,
      PromoCollections,
      ProductServiceId: productServiceId,
      Mail: Mail,
      Ingredients,
    };
  }

  detectProductType() {
    this.isPriceMultiplier = false;
    this.isProductWithOption = false;

    if (this.product?.IsDynamicSize || this.product?.ProductType === 'GiftCard') {
      this.isDisplayUnitPrice = false;
    }

    if (this.product?.OptionSets?.length === 1 && this.product?.IsDynamicSize) {
      this.isPriceMultiplier = true;
    }

    if (this.product?.OptionSets?.length && !this.product?.IsDynamicSize) {
      this.isProductWithOption = true;
    }
  }

  openSelectOptionModal() {
    if (this.product?.ProductType === 'GiftCard') {
      // Gift Card Product
      return this.openGiftCardOptionsModal();
    }

    // Regular Product
    return this.openProductOptionsModal();
  }

  async openProductOptionsModal() {
    const modal = await this.modalCtrl.create({
      cssClass: 'product-options-modal',
      component: ProductOptionsModalComponent,
      componentProps: {
        productOptionSet: this.product?.OptionSets,
        regularPrice: this.product?.DisplayPrice,
        productName: this.product?.DisplayName?.En || this.product?.Name?.En,
        shoppingMode: this.shoppingMode,
        rawProduct: this.productRes,
        productId: this.product?.ProductId,
        storeCode: this.store?.StoreCode,
        isEdit: this.isEdit,
        selectedOptionSets: this.selectedOptionSets,
        defaultImage: this.product?.Images,
        quantity: this.quantity,
        cartItemId: this.itemId?.length && this.itemId,
      },
      breakpoints: [0, 0.5, 1],
      initialBreakpoint: 1,
      handle: false,
    });

    modal.onDidDismiss().then();

    return await modal.present();
  }

  async openGiftCardOptionsModal() {
    const modal = await this.modalCtrl.create({
      cssClass: 'gift-card-options-modal',
      component: GiftCardOptionsModalComponent,
      componentProps: {
        giftCardOptions: this.product?.OptionSets,
        productName: this.product?.DisplayName?.En || this.product?.Name?.En,
        isEdit: this.isEdit,
        selectedOptionSets: this.selectedOptionSets,
        isInstoreOnly: this.isInstoreOnly,
        rawProduct: this.productRes,
        IsOutOfStock: this.product?.IsOutOfStock,
        shoppingMode: this.shoppingMode,
        productId: this.product?.ProductId,
        storeCode: this.store.StoreCode,
        quantity: this.quantity,
        defaultImage: this.product?.Images,
        cartItemId: this.itemId?.length && this.itemId,
      },
      breakpoints: [0, 0.5, 1],
      initialBreakpoint: 1,
      handle: false,
    });

    modal.onDidDismiss().then((detail: any) => {
      console.log('Gift card options selected  ====>', detail);
    });

    return await modal.present();
  }

  goCart() {
    this.router.navigate(['/cart']);
  }

  async changeFlavorProduct(product) {
    this.utils.showLoading();
    if (product)
      this.navCtrl.navigateForward([`/product/product-detail/${product.Upc}`], {
        replaceUrl: true,
        animated: false,
      });
    this.slug = product?.Upc;
  }

  async addToList() {
    if (!this.currentUser) {
      this.router.navigateByUrl('/sign-in', { replaceUrl: true });
      return;
    }
    this.isLoading = true;
    try {
      await this.shoppingListSvc.handleAddItemToCurrentShoppingList(this.product);
      const payload = { action: ActionType.MagRefreshShoppingList };
      window.postMessage(payload, window.location.origin);
    } catch (err) {
      console.warn('Error adding to list', err);
    } finally {
      this.isLoading = false;
    }
  }

  public getPageName() {
    return 'ProductDetailPage';
  }

  async getOffersForSimilarProduct(products) {
    const upcs = products.map((x) => x.Upc).filter(Boolean);
    try {
      const { ProductMappings, Offers } =
        (await firstValueFrom(this.productDealService.getOfferInfosByUpcs(upcs, this.store.StoreCode))) || {};

      if (!ProductMappings || !Offers) return;

      const offersByUpc = Object.fromEntries(ProductMappings?.map((item) => [item.Upc, item.OfferIds]));
      const list = products.map((x) => {
        const offerIds = offersByUpc[x.Upc];
        if (offerIds?.length) {
          x.Offers = Offers.filter((offer) => offerIds.includes(offer.Id));
        }
        return x;
      });

      this.similarProducts = JSON.stringify(list);
    } catch (error) {
      console.log('Fail fetching offers for similar products :', error);
    }
  }

  async refreshProductOffers() {
    this.productRes = await firstValueFrom(
      this.productService.getProductByUPC(this.slug, this.store?.StoreCode, false, this.currentUser)
    );

    // this.productOffers = this.productRes?.Offers;
    // don't need await offer load done
    firstValueFrom(this.productDealService.getOfferInfosByUpcs([this.slug], this.store?.StoreCode)).then((rs) => {
      if (rs?.Offers) {
        const offers = rs?.Offers;
        this.productOffers = offers?.filter(
          (x) =>
            x.DiscountType !== enumDiscountType.ExternalPromotion &&
            !(x.DiscountType === enumDiscountType.NewPrice && x.EffectValue === 0)
        );
      }
    });
  }

  async getStoreSystemServices() {
    try {
      const res = await firstValueFrom(this.storeService.getStoreSystemServices(true));
      if (res?.length > 0) {
        this.systemService = res.find((service) => toBoolean(service?.SettingAttributes?.is_default_shop_path?.Value));
      }
    } catch (error) {
      console.error('Error fetching system services', error);
    }
  }

  async isProductUnavailable() {
    const productServiceId = this.product?.ProductServiceId;
    const storeService = this.store?.StoreServices?.find((service) => service?.ServiceId === productServiceId);

    // Check fulfillment method support by product
    const productSupportPickup = String(this.product?.Pickup) === 'true';
    const productSupportDelivery = String(this.product?.Delivery) === 'true';

    const productDeliveryOnly = !productSupportPickup && productSupportDelivery;
    const productPickupOnly = productSupportPickup && !productSupportDelivery;

    // Check fulfillment method support by system service
    const allService = await firstValueFrom(this.storeService.getStoreSystemServices());
    const systemService = this.storeService.getSystemServiceById(productServiceId, allService);
    const { EnabledDelivery: SystemServiceSupportDelivery, EnabledPickup: SystemServiceSupportPickup } =
      systemService ?? {};

    const serviceDeliveryOnly = SystemServiceSupportDelivery && !SystemServiceSupportPickup;
    const servicePickupOnly = SystemServiceSupportPickup && !SystemServiceSupportDelivery;

    // Check out of stock
    const outOfStock = !!this.product?.IsOutOfStock || !!this.product?.IsOutOfStockAllStore;

    // Check if no service found
    const noServiceFound = !productServiceId || !storeService?.ServiceId;

    // Check if no service support product
    const noServiceSupportProduct =
      (serviceDeliveryOnly && productPickupOnly) || (servicePickupOnly && productDeliveryOnly);

    this.isUnavailable = outOfStock || noServiceFound || noServiceSupportProduct;
  }

  backPage() {
    this.navCtrl.back();
  }
}
