import { Component, EventEmitter, Input, OnInit, Output, OnDestroy } from '@angular/core';
import { ModalController } from '@ionic/angular';
import { IMagOption, IMagOptionSet } from '../../model/interface';
import { ProductService } from '../../providers/product.service';
import { BehaviorSubject, Subject, takeUntil } from 'rxjs';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import {
  checkOptionSetToDisplay,
  flattenOptionSets,
  formatGiftCard,
  formatSubmitGiftCardOptionSet,
  getOptionsByType,
  getSubmitOptionSetsForGiftCard,
} from '../../model/util';
import { cloneDeep } from 'lodash';

@Component({
  selector: 'gift-card-options-modal',
  templateUrl: 'gift-card-options-modal.html',
  styleUrls: ['gift-card-options-modal.scss'],
})
export class GiftCardOptionsModalComponent implements OnInit, OnDestroy {
  @Input() giftCardOptions: IMagOptionSet[];
  @Input() selectedOptionSets?: any;
  @Input() productName: string;
  @Input() shoppingMode?: string;
  @Input() isInstoreOnly = false;
  @Input() IsOutOfStock = false;
  @Input() rawProduct: string;
  @Input() storeCode: string;
  @Input() productId: string;
  @Input() isEdit: boolean;
  @Input() cartItemId: string;

  @Output() handleCloseModal: EventEmitter<any> = new EventEmitter();

  magQuanityBtn: string;
  giftCardStyles: IMagOptionSet;
  giftCardAmounts: IMagOptionSet;
  giftCardMessage: IMagOptionSet;

  amountOtherValue: number;
  totalVal: number;
  isOtherAmount = false;
  isOtherAmountInitialized = false;
  isAmountMaximum = false;
  isAmountMinimum = true;
  max: number;
  min: number;

  btnMode = 'MODAL';
  submitOptions: any = [];

  allOptionSetsWithSelectedValue: IMagOptionSet[] = [];
  renderOptionSets: IMagOptionSet[] = [];

  //ToDo: hard code for now
  gapAmount = 5;
  optionSetList = ['giftCardStyles', 'giftCardAmounts', 'giftCardMessage'];
  seletedOptions$ = new BehaviorSubject<IMagOptionSet[]>([]);
  private _destroy$: Subject<boolean> = new Subject();

  constructor(
    private modalCtrl: ModalController,
    public productService: ProductService,
    public dxpComponentService: DxpComponentService,
    public utils: Utils
  ) {}

  // Lifecycle hooks
  ngOnInit(): void {
    this.subscribeToSelectedOptions();
    this.allOptionSetsWithSelectedValue = formatGiftCard(
      cloneDeep(this.giftCardOptions),
      this.isEdit,
      this.selectedOptionSets
    );
    this.prepareRenderOptionSets(cloneDeep(this.allOptionSetsWithSelectedValue));
    window.addEventListener('actionSuccess', (event: CustomEvent) => this.handleActionSuccess(event));
  }

  private subscribeToSelectedOptions() {
    this.seletedOptions$.pipe(takeUntil(this._destroy$)).subscribe((options) => {
      if (options?.length) {
        this.optionSetList.forEach((option) => {
          this[option] = getOptionsByType(flattenOptionSets(options), option);
        });
        this.selectCustomValueOption();
        this.totalVal =
          this.isOtherAmountInitialized &&
          this.getTotalPrice(this.giftCardAmounts, this.isOtherAmount, this.amountOtherValue);
        this.transformDataForSubmit(options);
      }
    });
  }

  prepareRenderOptionSets(selectedOptionSets: IMagOptionSet[]) {
    const rs = selectedOptionSets?.filter((optionSet) => checkOptionSetToDisplay(optionSet, selectedOptionSets));
    this.seletedOptions$.next(rs);
  }

  ngOnDestroy(): void {
    this._destroy$.next(true);
    this._destroy$.complete();
    this.isEdit = false;
    this.isOtherAmountInitialized = false;
    window.removeEventListener('actionSuccess', (event: CustomEvent) => this.handleActionSuccess(event));
  }

  handleActionSuccess(event: CustomEvent) {
    if (event?.detail) {
      this.closeModal();
    }
  }

  getTotalPrice(optionSet: IMagOptionSet, isOtherAmount: boolean, amountOtherValue: number) {
    if (isOtherAmount) {
      return amountOtherValue;
    }
    return optionSet?.Options?.find((option) => option?.Code === optionSet?.SelectedOptionValue)?.PriceModifier;
  }

  setupOtherAmount() {
    if (this.isOtherAmountInitialized) return;
    const defaultPrice = this.giftCardAmounts?.Options[0]?.PriceModifier ?? 0;
    this.min = defaultPrice;
    this.max = 1000;
    if (this.isEdit) {
      const customValue = Number(this.giftCardAmounts?.CustumOptionValue);
      this.isOtherAmount = !isNaN(customValue);
      this.amountOtherValue = customValue || defaultPrice;
    } else {
      this.amountOtherValue = defaultPrice;
    }
    this.isOtherAmountInitialized = true;
  }

  transformDataForSubmit(optionSets: IMagOptionSet[]) {
    const submitOptionSetsForGiftCard = getSubmitOptionSetsForGiftCard(cloneDeep(optionSets));
    const submitOptionSets = submitOptionSetsForGiftCard?.map((optionSets) =>
      formatSubmitGiftCardOptionSet(optionSets)
    );
    if (submitOptionSets?.length) {
      this.submitOptions = submitOptionSets;
    }
  }

  selectCustomValueOption() {
    if (!this.giftCardAmounts || !this.giftCardAmounts.Options) return;
    const customValueOption = this.giftCardAmounts.Options.find(
      (option) => this.giftCardAmounts.SelectedOptionValue === option.Id
    );
    if (customValueOption && customValueOption?.Tags?.includes('customvalue')) {
      this.isOtherAmount = true;
      this.isAmountMaximum = false;
      this.isAmountMinimum = true;
      this.setupOtherAmount();
    }
  }

  handleChangeOption(option) {
    this.isOtherAmount = option?.Tags?.includes('customvalue');
    if (this.isOtherAmount) {
      this.isAmountMaximum = false;
      this.isAmountMinimum = true;
    }
    this.allOptionSetsWithSelectedValue = this.updateSelectedValue(
      this.allOptionSetsWithSelectedValue,
      option,
      'ParentId'
    );
    this.prepareRenderOptionSets(this.allOptionSetsWithSelectedValue);
    this.selectCustomValueOption();
  }

  updateSelectedValue(giftCardOptions: IMagOptionSet[], option: IMagOptionSet, keyCompare: string) {
    return giftCardOptions?.map((giftCardOption: IMagOptionSet) => {
      if (giftCardOption.Id === option[keyCompare]) {
        if (this.amountOtherValue) {
          return {
            ...giftCardOption,
            SelectedOptionValue: option.Id,
            CustumOptionValue: String(this.amountOtherValue),
          };
        }
        return {
          ...giftCardOption,
          SelectedOptionValue: option.Id,
        };
      } else {
        return {
          ...giftCardOption,
          OptionSets: this.updateSelectedValue(giftCardOption?.OptionSets, option, keyCompare),
        };
      }
    });
  }

  updateCustomValue(
    optionSets: Array<IMagOptionSet>,
    option: IMagOption,
    keyCompare: string,
    updateValue: { [key: string]: any }
  ) {
    return optionSets.map((optionSet) => {
      if (optionSet?.IsParent) {
        const optionSets = this.updateCustomValue(optionSet?.OptionSets, option, keyCompare, updateValue);
        if (optionSets) {
          return {
            ...optionSet,
            OptionSets: optionSets,
          };
        }
        return { ...optionSet };
      } else if (optionSet[keyCompare] === option[keyCompare]) {
        const options = {
          ...optionSet,
          ...updateValue,
        };
        return options;
      }
      return optionSet;
    });
  }

  handleChangeOtherAmount(isIncrease: boolean, amountObj) {
    if (!this.gapAmount) return;

    if (isIncrease && this.amountOtherValue + this.gapAmount <= this.max) {
      this.amountOtherValue += this.gapAmount;
    }
    if (!isIncrease && this.amountOtherValue - this.gapAmount >= this.min) {
      this.amountOtherValue -= this.gapAmount;
    }

    this.isAmountMaximum = this.amountOtherValue + this.gapAmount > this.max;
    this.isAmountMinimum = this.amountOtherValue - this.gapAmount < this.min;
    // const updatedOptionSet = this.allOptionSetsWithSelectedValue.find((optionSet) => optionSet.Code === amountObj.Code);
    // updatedOptionSet.CustumOptionValue = String(this.amountOtherValue);
    const updateValue = {
      CustumOptionValue: String(this.amountOtherValue),
    };
    this.allOptionSetsWithSelectedValue = this.updateCustomValue(
      this.allOptionSetsWithSelectedValue,
      amountObj,
      'Code',
      updateValue
    );
    this.prepareRenderOptionSets(this.allOptionSetsWithSelectedValue);
  }

  hanldeChangeMesage(message: string, messageObj) {
    // const updatedOptionSet = this.allOptionSetsWithSelectedValue.find((optionSet) => optionSet.Code === messageObj.Code);
    // updatedOptionSet.SelectedOptionValue = message;
    const updateValue = {
      SelectedOptionValue: message,
    };
    this.allOptionSetsWithSelectedValue = this.updateCustomValue(
      this.allOptionSetsWithSelectedValue,
      messageObj,
      'Code',
      updateValue
    );
    this.prepareRenderOptionSets(this.allOptionSetsWithSelectedValue);
  }

  // Modal functions
  closeModal() {
    return this.modalCtrl.dismiss();
  }
}
