import { Component, Input, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Utils } from '@rsApp/modules/utils/providers/utils';

@Component({
  selector: 'parity-product-size',
  templateUrl: 'parity-product-size.html',
  styleUrls: ['parity-product-size.scss'],
})
export class ParityProductSizeComponent implements OnInit {
  @Input() parityName = 'Sizes (3 Available)';
  @Input() listProduct: any[] = [
    {
      id: '1',
      imageName: 'Mercatus Photo Cakes',
      name: 'Sheet Cake - 1/4 Sheet',
      imageUrl: 'assets/img/ecom-v2/parity-prod-size-1.png',
      price: '$19.99 ea',
    },
    {
      id: '2',
      imageName: 'Mercatus Photo Cakes',
      name: 'Sheet Cake - 1/2 Sheet',
      imageUrl: 'assets/img/ecom-v2/parity-prod-size-2.png',
      price: '$1.29 ea',
    },
    {
      id: '3',
      imageName: 'Mercatus Photo Cakes',
      name: 'Sheet Cake - Full Sheet',
      imageUrl: 'assets/img/ecom-v2/parity-prod-size-3.png',
      price: '$1.29 ea',
    },
  ];

  selectedProduct: any;
  isExpand = false;

  constructor(
    public router: Router,
    public utils: Utils,
    public route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    this.selectedProduct = this.listProduct.find((p) => p.id === '1');
  }

  onSelectProduct(product: any) {
    this.selectedProduct = product;
    console.log('Selected Size: ', this.selectedProduct);
  }

  onClickDropdowIcon(event) {
    event.stopPropagation();
    this.isExpand = !this.isExpand;
  }
}
